insert into public.treatments (slug, name, menu_name, alternate_name, summary, procedure, national_range, cost_factors, desk_work, card_blurb, icon, related, read_slugs, video_slugs, reviewer_id, content, display, images, published) values
  ('gynecomastia-surgery', 'Gynecomastia surgery', 'Gynecomastia surgery', 'Male breast reduction', 'Surgery for enlarged chest tissue in men: fat removed by liposuction, gland cut out, or both.', '{"procedureType":"https://schema.org/SurgicalProcedure","bodyLocation":"Chest","howPerformed":"Fat is removed by liposuction, breast gland tissue is cut out through a small cut at the edge of the areola or the side of the chest, or both; extra skin is removed or tightened in large cases.","preparation":"Examination by a surgeon, review of medicines, blood tests and an anaesthesia fitness check.","followup":"Compression garment, review visits, and a gradual return to exercise as the surgeon advises."}'::jsonb, '{"minInr":58000,"maxInr":98000,"fromInr":42000,"validAsOf":"2026-11","isSample":true}'::jsonb, '[{"factor":"Grade and method","why":"Liposuction alone takes less theatre time than gland removal with skin removal."},{"factor":"Anaesthesia","why":"General anaesthesia costs more than local with sedation."},{"factor":"Hospital type","why":"A day-care centre and a multi-specialty hospital price rooms and theatre differently."},{"factor":"City","why":"Rents and wages differ between cities, and so do facility fees."},{"factor":"Stay","why":"Day care at the lower end, one night in a room at the upper."},{"factor":"Garment and medicines","why":"Brand and number of garments, and the medicines prescribed."},{"factor":"Follow-up visits","why":"Some quotes include them, some charge per visit."},{"factor":"A second operation","why":"Some hospitals include a touch-up for a period, some charge in full."}]'::jsonb, 'About 1 week', 'The full procedure guide: who it suits, how it is done, recovery.', 3, '["liposuction","tummy-tuck"]'::jsonb, '["gynecomastia-grades","gynecomastia-fat-or-gland","pseudogynecomastia"]'::jsonb, '["gynecomastia-explained","gynecomastia-recovery-weeks"]'::jsonb, null, '{"dek":"Surgery removes extra chest gland, fat or both, and a surgeon decides which after an examination. Here is what [gynecomastia surgery](/gynecomastia-surgery) involves, when you can work, drive and train, and how we check a surgeon. The [national cost factors](/cost/gynecomastia-surgery) are on their own page.","shortAnswers":[{"q":"Do I even need surgery?","a":"It depends on whether the enlargement is gland, fat or both. Only an examination can tell. Many teenagers settle without surgery.","href":"#fat-or-gland","linkText":"Gland or fat"},{"q":"What will it cost?","a":"One bill with the surgeon, anaesthesia and facility fees in it, and a few items to ask for in writing. The range shown is to be confirmed.","href":"#cost","linkText":"The lines"},{"q":"How long until I can work and drive?","a":"Desk work after about a week, driving after about two, chest training after six or more.","href":"#recovery","linkText":"The calendar"},{"q":"Who operates, and who checks them?","a":"No surgeon is listed yet. We list one only after registration and accreditation are checked.","href":"#choose","linkText":"The checks"}],"operation":{"lead":"Gynecomastia is growth of the breast gland in boys and men, on one side or both. Surgery takes out fat, gland or both, and the plan depends on what an examination finds.","body":"Your surgeon may suggest [liposuction only or gland removal](/learn/gynecomastia-liposuction-vs-gland-removal), or the two together. [Liposuction](/liposuction) reaches the fat through tiny cuts, and some surgeons use ultrasound- or power-assisted tools for it. Gland tissue is firm and has to be cut out, usually through a small cut at the edge of the areola or the side of the chest. Larger cases also need skin removal or tightening. The [grades of gynecomastia](/learn/gynecomastia-grades) help the surgeon choose.","caption":"Two common approaches, drawn side by side.","ask":"Is mine gland, fat or both, and what would you do about each part?","how":["**Liposuction:** fat is suctioned out through tiny cuts. A few very small marks.","**Gland removal:** the gland is cut out through a small cut at the edge of the areola or the side of the chest. One small line.","**Skin removal or tightening:** extra skin is cut away, or tightened with radiofrequency energy in some cases. Longer scars if skin is cut away.","Smaller operations may use local anaesthesia with sedation, larger ones general anaesthesia. Many are day care; some need one night. A thin drain is sometimes placed for a day or two."],"whoItSuits":[{"term":"Health","text":"Good general health, a weight that has been steady for some months, and no smoking if you can manage it."},{"term":"Expectations","text":"A clear idea of what surgery can change. Scars remain and the result depends on your body."},{"term":"Reason","text":"The chest bothers you in daily life: clothes, the gym, swimming, or how you feel about it."},{"term":"Who asks","text":"Teenagers and their parents, bodybuilders, men in desk jobs, and older men with loose skin. Each group has a different first question, and the surgeon''s answer differs too."}]},"fatOrGland":{"lead":"The two look alike in a mirror and feel different to the hand. Only a doctor can tell after an examination, and may ask for an ultrasound or blood tests.","body":"Hormone balance, some medicines and recent weight change can all cause chest enlargement, so see a doctor before you plan surgery. Read about [fat or gland](/learn/gynecomastia-fat-or-gland) and [chest fat without gland](/learn/pseudogynecomastia). Many teenagers settle without an operation, and some [possible causes](/learn/gynecomastia-causes) can be treated first. For [what exercise can change](/learn/male-chest-exercise-and-fat), see our short guide.","term":"**Pseudogynecomastia** is chest fat that looks like gland. Many men have a mix of the two.","tissueTable":[{"feature":"Feel","gland":"Firm, rubbery disc","fat":"Soft, spread across the chest"},{"feature":"Where","gland":"Behind the nipple","fat":"All over the chest, often the sides too"},{"feature":"Tenderness","gland":"Often tender to touch","fat":"Usually not tender"},{"feature":"Weight loss","gland":"Changes little","fat":"Often reduces"}],"seeDoctor":"A hard lump, one side only, pain or nipple discharge. Do this before you plan surgery.","causes":["Hormone balance: relatively more oestrogen than testosterone, as in puberty, later life or some illnesses.","Some medicines, for example certain antibiotics, anxiety medicines and treatments for the prostate or the stomach.","Alcohol, anabolic steroids and some drugs.","Medical conditions such as kidney, liver or thyroid problems."],"symptoms":["A lump or firm disc behind the nipple, on one or both sides.","Swelling that is uneven between the two sides.","Tenderness, or a wider areola.","Fluid from the nipple. This needs a doctor''s check soon."],"myths":["Creams, oils, homeopathy and fat-burner supplements: there is no good evidence that any of them removes gland tissue.","Chest exercise: it builds muscle under the tissue and can make a gland look more prominent, not smaller.","\"It is always just fat\": not so. Many men have gland, and gland does not shrink with diet."],"gradesCaption":"Grades of gynecomastia, and the usual approach. Scales differ between surgeons, so yours will explain theirs.","grades":[{"grade":"I","looks":"Small mound around the nipple, no loose skin","approach":"Liposuction, or gland removal if firm"},{"grade":"II","looks":"Larger, with more fat around it, no loose skin","approach":"Gland removal with liposuction"},{"grade":"III","looks":"Moderate, with loose skin","approach":"As II, and sometimes skin removal"},{"grade":"IV","looks":"Large, with loose skin","approach":"Skin removal, often in two stages"}]},"recovery":{"lead":"Typical timing for an uncomplicated operation. Your surgeon sets yours. {pending}","body":"A compression vest is worn for the first weeks, under clothes, as the surgeon advises. Summers here are hot, so ask for a breathable garment and a spare. The [full recovery guide](/gynecomastia-surgery#recovery) has the detail.","highlights":[{"pre":"about","big":"1 week","text":"Desk work, with some soreness"},{"pre":"about","big":"2 weeks","text":"Driving, if the surgeon agrees"},{"big":"6 weeks","post":"or more","text":"Chest and arm training, if the surgeon agrees"}],"timeline":[{"when":"Day 0","notice":"Drowsy after anaesthesia, chest wrapped","doThis":"Home the same day or after one night. An attendant stays with you. Garment on."},{"when":"Day 1 to 2","notice":"Soreness and tightness, some swelling","doThis":"Rest, with light movement indoors. Pain medicine as prescribed. WhatsApp check-in from us on day 1."},{"when":"Day 3 to 7","notice":"Bruising and swelling at their most, then easing","doThis":"Short walks. Desk work from home from about day 5 to 7 if you feel ready. Drain out, if one was placed."},{"when":"Week 2","notice":"Bruising fading, chest feels tight","doThis":"Office, and driving if the surgeon agrees. Brisk walking or cycling if comfortable. Review visit. Stitches checked."},{"when":"Week 4","notice":"Swelling lessening, numb patches common","doThis":"Light leg gym. Garment continues as advised."},{"when":"Week 6","notice":"Chest feels more normal","doThis":"Heavy lifting, chest press and swimming only if the surgeon agrees."},{"when":"Week 12","notice":"Most swelling settled, scars still pink","doThis":"Review visit. Flights and long drives as the surgeon advises."}],"grid":{"cols":["Day 1","Wk 1","Wk 2","Wk 4","Wk 6+"],"rows":[{"label":"Desk work","cells":[{"state":"n","text":"No"},{"state":"m","text":"Some"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"}]},{"label":"Driving","cells":[{"state":"n","text":"No"},{"state":"m","text":"Ask"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"}]},{"label":"Walking","cells":[{"state":"m","text":"Short"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"}]},{"label":"Leg gym","cells":[{"state":"n","text":"No"},{"state":"n","text":"No"},{"state":"m","text":"Light"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"}]},{"label":"Chest, arms","cells":[{"state":"n","text":"No"},{"state":"n","text":"No"},{"state":"n","text":"No"},{"state":"m","text":"Ask"},{"state":"m","text":"If ok"}]}]},"closing":"Ask before booking a flight in the first weeks. Some soreness and swelling are expected, and swelling takes months to settle."},"risks":{"lead":"Every operation has risks. These are the ones to ask about, in plain words. No frequencies are shown here, because we show a figure only when a named source backs it.","rows":[{"risk":"Bleeding","means":"Blood collects under the skin and may need draining","ask":"Whether a drain is used, and what to watch for at home"},{"risk":"Fluid or infection","means":"Fluid collects (a seroma), or the wound gets infected","ask":"Which signs mean a same-day call, and whose number to use"},{"risk":"Uneven chest","means":"Dents, lumps, or one side that differs from the other","ask":"How the surgeon checks both sides before you leave theatre"},{"risk":"Nipple feeling","means":"Numbness or extra sensitivity, usually easing over months","ask":"How long it can last in your case"},{"risk":"Scars and loose skin","means":"Scars fade over a year or more; loose skin may remain","ask":"To see where the cuts will be marked"},{"risk":"Slow healing","means":"A wound heals late, and in rare cases some tissue is lost","ask":"What raises the chance, such as smoking, and what to stop beforehand"},{"risk":"Anaesthesia and medicines","means":"Allergic reactions and, rarely, a blood clot","ask":"Who gives the anaesthesia, and what the fitness check covers"},{"risk":"Coming back","means":"Weight gain, some medicines and steroids can bring new enlargement","ask":"What to avoid, and what to do if it returns"},{"risk":"A second operation","means":"A touch-up may be needed after the first","ask":"Whether it is charged, and for how long after the first"}],"alert":"**Call the hospital the same day** for fever, spreading redness, fast swelling on one side, bleeding through the dressing or severe pain. Chest pain or breathlessness: call 112.","wait":["Your chest is still changing, or it started recently.","You use steroids or testosterone products. Stopping may help.","A liver, kidney or thyroid problem has not been looked at.","You plan to lose a lot of weight soon, or you smoke."],"tell":["Every medicine and supplement, including gym supplements.","Alcohol and cannabis use.","When the enlargement began, and whether it changed in the last year."]},"patientQuestions":[{"q":"Will anyone at work come to know I had this done?","href":"#getting-there","linkText":"Read: getting there and staying"},{"q":"I am 19. Is it too early to think about surgery?","href":"#fat-or-gland","linkText":"Read: is it fat or gland"},{"q":"Do I need to stop my gym routine before and after?","href":"#recovery","linkText":"Read: recovery calendar"},{"q":"Can I take a flight or a long drive a few days later?","href":"#recovery","linkText":"Read: recovery calendar"},{"q":"Is one side done first, or both together?","href":"#surgery","linkText":"Read: the operation"},{"q":"How do I know if it is fat, or a gland?","href":"#fat-or-gland","linkText":"Read: is it fat or gland"}],"quoteProcess":[{"title":"You talk to a coordinator","text":"In person, by WhatsApp or by phone, whichever you choose. No pressure to book."},{"title":"A surgeon examines you","text":"Gland or fat, and the grade, are decided in person, not on the phone."},{"title":"The hospital writes the cost","text":"Surgeon, anaesthesia and facility fees, plus the items it adds, listed one by one."},{"title":"You pick the anaesthesia and the date","text":"The surgeon and the anaesthetist advise. Most operations are day care."},{"title":"After the operation","text":"A check-in from us on day 1, a compression vest, review visits, and a staged return to work and training."}],"quoteChecks":["list the surgeon, anaesthesia and facility fees separately?","say whether a second operation is included, and for how long?","name the same room, day care or overnight?","write down the number of follow-up visits?"],"extras":["Tests before surgery","Compression garment","Medicines for the first days","Follow-up visits","Treating a complication","A second operation","Loose skin, if added later","Your attendant''s stay and travel"],"insurance":"**Insurance.** Gynecomastia surgery is usually treated as cosmetic, and most policies do not pay for cosmetic surgery. A policy may consider it when a doctor records a medical need. Read your policy, ask your insurer in writing before you book, and keep the estimate and the diagnosis. We do not promise cashless approval.","payment":"**Payment.** Cash, cards and instalments through a lender may be possible. Terms and fees depend on the hospital and the lender and are not shown here. {tbc}","sources":[{"label":"NHS: Gynaecomastia","href":"https://www.nhs.uk/conditions/gynaecomastia/"},{"label":"Mayo Clinic: Gynecomastia","href":"https://www.mayoclinic.org/diseases-conditions/gynecomastia/symptoms-causes/syc-20351793"},{"label":"National Medical Commission: public register of doctors","href":"https://www.nmc.org.in/"}],"footnotes":["Medical review is pending. The reviewer, qualification and review date shown are sample data and will be replaced by the real ones.","The range is a working figure from the partner side. It still has to be confirmed in writing for Bestdoctorsin and the partner hospital, and it will carry a date.","Typical timings for an uncomplicated operation, to be confirmed by the reviewer. Your surgeon''s advice overrides this page.","Insurance wording is general and is to be confirmed by the reviewer. Your policy document decides.","Several grading scales are in use and they do not match exactly. The four grades here are a plain summary, not a quotation of one scale. Studies on technique and recovery will be read and cited here after the reviewer checks each one."]}'::jsonb, null, '{"hero":{},"operation":{},"recovery":{},"card":{}}'::jsonb, true),
  ('liposuction', 'Liposuction', 'Liposuction', 'Body contouring', 'Removes stubborn pockets of fat from areas such as the abdomen, flanks, thighs, arms, chest and chin. Not a weight-loss treatment.', '{"procedureType":"https://schema.org/SurgicalProcedure","bodyLocation":"Abdomen, waist, thighs, hips, arms, back, chest, chin and neck","howPerformed":"Fat is loosened and drawn out through tiny cuts with a thin tube, sometimes with ultrasound, power or laser assistance; a solution is often put into the fat first.","preparation":"Examination by a surgeon, review of medicines, blood tests and an anaesthesia fitness check.","followup":"Compression garment, a first review about three to five days later, more review visits, and a gradual return to exercise as the surgeon advises."}'::jsonb, '{"minInr":60000,"maxInr":80000,"validAsOf":"2026-11","isSample":true}'::jsonb, '[{"factor":"Areas treated","why":"The abdomen, flanks, thighs, arms, back, chest and chin differ in size, depth of fat and skin."},{"factor":"Number of areas","why":"Two or more areas take longer, need a bigger anaesthetic plan and usually cost more."},{"factor":"Technique","why":"Ultrasound-assisted and other equipment-based methods are priced differently from standard suction."},{"factor":"Amount of fat removed","why":"More fat means more time, and may mean a night in hospital."},{"factor":"Hospital charges","why":"A day-care centre and a multi-specialty hospital price theatre and rooms differently."},{"factor":"Anaesthesia","why":"General anaesthesia costs more than local with sedation."},{"factor":"Garments and follow-up","why":"Number of garments, and whether review visits are included or charged one by one."},{"factor":"A second operation","why":"Some quotes include a touch-up for a period, some charge in full."}]'::jsonb, 'About 1 to 2 weeks', 'Removes stubborn fat from chosen areas. Not for weight loss.', 1, '["gynecomastia-surgery","tummy-tuck"]'::jsonb, '["liposuction-vs-weight-loss","liposuction-recovery-timeline","liposuction-body-areas"]'::jsonb, '[]'::jsonb, null, '{"dek":"Liposuction removes pockets of fat that diet and exercise did not shift, from areas such as the abdomen, flanks, thighs, arms or chin. It is not weight loss. Here is what [liposuction](/liposuction) involves, what changes the price area by area, how recovery runs, and how we check a surgeon. The [national cost factors](/cost/liposuction) are on their own page.","shortAnswers":[{"q":"Is liposuction a way to lose weight?","a":"No. It reshapes stubborn pockets of fat in one or more areas. It is not a treatment for obesity, and the surgeon will ask you to be near a steady weight first.","href":"#surgery","linkText":"What it does"},{"q":"What will it cost?","a":"It depends on the area, the number of areas and the technique, so the price is shown area by area, not as one headline figure. The ranges are to be confirmed.","href":"#cost","linkText":"The price table"},{"q":"How long until I am back to normal?","a":"Most people rest for a few days, return to desk work within one to two weeks and build up exercise over four to six weeks. The contour keeps settling for months.","href":"#recovery","linkText":"The calendar"},{"q":"Who operates, and who checks them?","a":"No surgeon is listed yet. We list one only after registration and accreditation are checked.","href":"#choose","linkText":"The checks"}],"operation":{"lead":"Liposuction takes out localised fat through tiny cuts, using a thin tube. It shapes the body. It does not treat weight, and fat cells left in untreated areas can still grow if weight is gained.","body":"The surgeon marks the areas while you stand, then you have anaesthesia, which may be local with sedation or general depending on how much is being treated. A salt-water solution with a numbing medicine is often put into the fat first, so there is less bleeding and discomfort. Fat is then loosened and drawn out, the shape is checked from several sides, and the cuts are closed. You wear a compression garment afterwards. [Chest fat in men](/learn/liposuction-for-men) can be treated this way too, and when the cause is gland tissue rather than fat, the plan is different: see [gynecomastia surgery](/gynecomastia-surgery).","caption":"Fat removed through tiny cuts with a thin tube.","ask":"Which areas will you treat, which technique and why, how much fat do you expect to remove, and what is the plan if one side needs touching up later?","how":["Consultation: history, medicines, examination, and tests the surgeon asks for. An anaesthesia fitness check follows.","Planning: the surgeon marks the areas standing up and agrees the goal with you, including what liposuction cannot do.","Anaesthesia: local with sedation for a small area, general for larger or several areas. The surgeon and the anaesthetist decide.","The operation: tiny cuts, a solution into the fat, loosening and removal of fat, then a check of the contour and closure.","Straight after: a compression garment, a short stay in recovery, and written instructions. Some people go home the same day and some stay a night, depending on the areas and the anaesthesia.","Follow-up: a first review in the first week, usually around day 3 to 5, then more visits as the surgeon plans."],"whoItSuits":[{"term":"Often suits","text":"Adults in good general health, near a steady weight, with firm skin and a pocket of fat that has not moved with diet and exercise."},{"term":"Needs a different plan","text":"Loose skin or a stretched abdominal wall is not fixed by liposuction. See [liposuction or tummy tuck](/learn/liposuction-vs-tummy-tuck)."},{"term":"Often asked to wait","text":"A recent big change in weight, smoking, pregnancy or plans for it, and some health conditions. The surgeon decides after an examination."},{"term":"Not a substitute for","text":"Weight loss, or a treatment for obesity. See [liposuction is not weight loss](/learn/liposuction-vs-weight-loss)."}]},"areas":{"lead":"Surgeons commonly treat the abdomen, waist and flanks, thighs and hips, buttocks, the bra-strap area of the back, the upper arms, the chest, and the chin and neck. Each area behaves differently, and that is why the price depends on the area.","body":"How many areas are treated, how much fat sits in each, and how elastic the skin is all change the plan. A small, firm-skinned area may need one short session. Several areas at once take longer, need a larger anaesthetic plan and cost more. Read [which body areas liposuction can treat](/learn/liposuction-body-areas) for a closer look at each one.","rows":[{"area":"Abdomen","usual":"Often the largest single area","depends":"How far the fat extends, and whether loose skin or weak muscle is the real issue"},{"area":"Waist and flanks","usual":"Often paired with the abdomen","depends":"Number of zones treated, front to back"},{"area":"Thighs and hips","usual":"Inner, outer or both","depends":"Volume of fat, and skin tone after the fat is removed"},{"area":"Upper arms","usual":"Usually a smaller area","depends":"Skin elasticity: loose skin may need more than liposuction"},{"area":"Back, bra-strap area","usual":"Treated in zones","depends":"Number of zones and the depth of fat"},{"area":"Chest in men","usual":"Fat only, or with gland removal","depends":"Whether it is fat or gland: see [gynecomastia surgery](/gynecomastia-surgery)"},{"area":"Chin and neck","usual":"Small area, short operation","depends":"Technique, and whether skin or muscle under the chin is also a cause"}],"note":"Which areas, how many and in what order is a surgeon''s decision after an examination. A photo or a phone call cannot settle it."},"techniques":{"lead":"Several techniques exist, and a surgeon may combine them. The choice depends on the area, the amount of fat, the skin, earlier procedures and what you want. No technique suits everyone, and this page does not rank them.","rows":[{"name":"Tumescent","how":"A salt-water solution with a numbing medicine and a medicine that narrows blood vessels is put into the fat, then the fat is drawn out.","often":"The base of most plans; used with the others","ask":"How much solution and what limit do you keep for one session?"},{"name":"Ultrasound-assisted","how":"Sound energy loosens fat before it is drawn out. A surgeon may choose it for denser fat or for finer shaping.","often":"Denser areas such as the back or the male chest","ask":"Why this technique for my area, and does it change the price?"},{"name":"Power-assisted","how":"The tube moves with a small motor, so the surgeon makes shorter strokes.","often":"Larger volumes, or repeat work","ask":"Does it change the time under anaesthesia?"},{"name":"Laser-assisted","how":"Laser energy warms and loosens fat before removal, and some surgeons use it to tighten skin slightly.","often":"Small areas and some neck or chin plans","ask":"What does it add over the standard approach in my case?"},{"name":"Traditional suction","how":"The surgeon moves a thin tube by hand to break up and draw out fat.","often":"Many routine cases","ask":"Is this enough for the areas I have chosen?"}],"note":"Newer does not mean better for you. Ask the surgeon to explain the choice and what it does to the quote. See [types of liposuction](/learn/types-of-liposuction)."},"compare":{"tummyTuckLead":"Liposuction and a tummy tuck solve different problems. Liposuction removes fat. A tummy tuck removes loose skin and tightens the abdominal muscle wall. Some people need one, some need both, and a surgeon decides after an examination.","tummyTuck":[{"feature":"What it changes","lipo":"Fat in a chosen area","tuck":"Loose skin and a stretched muscle wall"},{"feature":"Cuts","lipo":"Tiny cuts, a few millimetres","tuck":"A long cut low on the abdomen, and one around the navel"},{"feature":"Skin","lipo":"Does not remove loose skin","tuck":"Removes extra skin"},{"feature":"Recovery","lipo":"Usually shorter","tuck":"Usually longer, with more restriction early on"},{"feature":"Often chosen when","lipo":"Skin is firm and fat is the main issue","tuck":"Skin is loose or muscles have parted, for example after pregnancy or a large weight change"}],"nonSurgicalLead":"Several non-surgical options are described for small pockets of fat. They are different from surgery, and this page has no comparison data on how much each changes in how many sessions.","nonSurgical":[{"name":"Fat freezing","text":"A device cools the skin over a pocket of fat. It is done in sessions and no cuts are made."},{"name":"Radiofrequency","text":"A device warms the tissue in sessions, and is also used for skin tightening."},{"name":"Laser and ultrasound devices","text":"Energy devices used over the skin in sessions."},{"name":"Fat-dissolving injections","text":"Injections into a small pocket, such as under the chin, usually in more than one session."},{"name":"Muscle stimulation","text":"A device that makes muscles contract, sometimes combined with other tools."}],"nonSurgicalNote":"Each usually changes less per session than surgery, and results vary between people. Ask any provider for written details of what was done for people like you, how many sessions are planned and what each costs. See [fat freezing, laser, RF or liposuction](/learn/liposuction-vs-non-surgical-fat-reduction).","whoShouldWait":["Your weight is still changing","You are pregnant or planning a pregnancy soon","You smoke and have not been able to stop","A health condition is not under control","You expect liposuction to replace weight loss"]},"recovery":{"lead":"Recovery runs in stages, and the contour keeps improving for months. These are typical timings for an uncomplicated operation, {pending} and your surgeon''s advice overrides this page.","body":"Swelling and bruising are normal at first and hide the final shape. The compression garment helps the skin settle against the new contour. You will usually have a review in the first week, and more visits afterwards. Plan leave and travel around the first review, not around the operation date. The [week by week recovery guide](/learn/liposuction-recovery-timeline) goes into more detail.","highlights":[{"pre":"Rest for","big":"2 to 3","post":"days","text":"Swelling, soreness and bruising are usual"},{"pre":"Review at","big":"day 3 to 5","text":"The first check, and a garment fit"},{"pre":"Back to routine in","big":"2 to 4","post":"weeks","text":"Desk work often sooner, if the surgeon agrees"},{"pre":"Shape settles by","big":"6 to 12","post":"months","text":"Swelling fades slowly, and skin adjusts"}],"timeline":[{"when":"Day 0 to 3","notice":"Soreness, swelling, bruising, fluid leaking from the cuts, tiredness","doThis":"Rest, short walks in the house, garment on, medicines as advised, plenty of fluids"},{"when":"Week 1","notice":"Swelling peaks and bruises change colour; the first review","doThis":"Light movement; the surgeon may allow a shower and desk work soon after"},{"when":"Weeks 2 to 4","notice":"Less soreness, uneven swelling, numb or tight skin","doThis":"Gradual return to routine; light massage only if the surgeon advises it"},{"when":"Weeks 4 to 6","notice":"Comfort improves, firmness may remain","doThis":"Step up activity as the surgeon allows; heavy lifting and hard training after approval"},{"when":"Months 2 to 3","notice":"The contour is clearer; some swelling remains","doThis":"Normal exercise if approved; garment as the surgeon sets"},{"when":"Months 6 to 12","notice":"Final shape; scars fade and soften","doThis":"Keep a steady weight; ask about any area that looks uneven before deciding on touch-ups"}],"grid":{"cols":["Day 1 to 3","Week 1","Week 2","Weeks 4 to 6"],"rows":[{"label":"Desk work","cells":[{"state":"n","text":"No"},{"state":"m","text":"Ask"},{"state":"y","text":"Often"},{"state":"y","text":"Yes"}]},{"label":"Driving","cells":[{"state":"n","text":"No"},{"state":"n","text":"No"},{"state":"m","text":"Ask"},{"state":"y","text":"Yes"}]},{"label":"Walking","cells":[{"state":"y","text":"Short"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"}]},{"label":"Gym","cells":[{"state":"n","text":"No"},{"state":"n","text":"No"},{"state":"n","text":"No"},{"state":"m","text":"Ask"}]},{"label":"Flying","cells":[{"state":"n","text":"No"},{"state":"n","text":"No"},{"state":"m","text":"Ask"},{"state":"y","text":"Often"}]}]},"closing":"Bring up any pain that is getting worse, a fever, a hot or red area, a swollen calf or breathlessness with your doctor straight away. Do not wait for the next visit."},"risks":{"lead":"Every operation carries risk. These are the ones people most often ask about, in plain words, and what you can do or ask. This is not a complete list, and the surgeon will go through yours.","rows":[{"risk":"Bruising and swelling","means":"Common, and expected for weeks. They hide the final shape.","ask":"How long should I expect it, and what is normal for my areas?"},{"risk":"Numbness or changed feeling","means":"Often temporary. A patch can stay different for longer.","ask":"How long can this last in my area?"},{"risk":"Uneven contour or lumps","means":"The surface can look uneven, and one side can differ from the other.","ask":"How do you check the shape during the operation, and when is a touch-up considered?"},{"risk":"Fluid collection (seroma)","means":"Fluid can gather under the skin and may need draining.","ask":"How will it be checked, and who drains it?"},{"risk":"Bleeding or a blood collection (haematoma)","means":"Uncommon. May need treatment.","ask":"What is your plan if it happens?"},{"risk":"Infection","means":"Possible after any cut. Early treatment matters.","ask":"Which signs should make me call, and who do I call?"},{"risk":"Loose skin","means":"Skin may not tighten fully after fat is removed, especially with low elasticity.","ask":"Will my skin tighten, and what is the plan if it does not?"},{"risk":"Scars and marks","means":"Tiny scars remain. Colour changes can occur.","ask":"Where will the cuts be, and how do you place them?"},{"risk":"Clots and anaesthesia risks","means":"Rare, but serious when they happen. Larger operations raise the risk.","ask":"What do you do to lower the risk of clots, and what are my own risk factors?"},{"risk":"A second operation","means":"Sometimes needed to improve the shape.","ask":"Is a second operation charged, and for how long after the first?"}],"alert":"Call your doctor straight away for a fever, spreading redness or heat, a swollen painful calf, chest pain, breathlessness, heavy bleeding or pain that keeps getting worse. If you cannot reach the doctor, go to the nearest emergency department. See [liposuction risks](/learn/liposuction-risks).","wait":["Your weight is still changing","You smoke and have not stopped","A health condition or a medicine needs adjusting first","You are pregnant, or planning a pregnancy soon","You have had a recent illness or infection"],"tell":["All your medicines and supplements, including blood thinners","Earlier operations and any problems with anaesthesia","Any history of blood clots, in you or your family","Allergies, especially to medicines or dressings","Smoking, alcohol, and any steroid or supplement use"]},"patientQuestions":[{"q":"I have tried gym and diet for years. Is this the next step?","href":"#surgery","linkText":"Read: the operation"},{"q":"Will I be able to work from home the next day?","href":"#recovery","linkText":"Read: recovery calendar"},{"q":"Can two or three areas be done together?","href":"#areas","linkText":"Read: areas and techniques"},{"q":"Will the fat come back?","href":"#faq","linkText":"Read: questions"},{"q":"Is it better to have a tummy tuck?","href":"#compare","linkText":"Read: tummy tuck and other options"},{"q":"Does a men''s chest or love-handle plan differ?","href":"#areas","linkText":"Read: areas and techniques"}],"quoteProcess":[{"title":"You talk to a coordinator","text":"In person, by WhatsApp or by phone, whichever you choose. Tell us which areas bother you. No pressure to book."},{"title":"A surgeon examines you","text":"Areas, technique and anaesthesia are decided in person, not by phone or from a photo."},{"title":"The hospital writes the cost","text":"The surgeon, anaesthesia and facility fees, plus garments, tests and follow-up visits, listed one by one."},{"title":"You pick the date","text":"The surgeon and the anaesthetist advise on day care or a night''s stay."},{"title":"After the operation","text":"A check-in from us on day 1, a compression garment, review visits and a staged return to routine."}],"quoteChecks":["list the areas treated and the technique?","list the surgeon, anaesthesia and facility fees separately?","say whether the compression garment is included?","write down the number of follow-up visits?","say whether a second operation is included, and for how long?"],"extras":["Tests before surgery","Compression garments (and a spare)","Medicines for the first days","Follow-up visits","Treating a complication","A second operation or touch-up","An overnight stay, if the surgeon asks","Your attendant''s stay and travel"],"insurance":"**Insurance.** Liposuction is usually treated as cosmetic, and most policies do not pay for cosmetic surgery. Read your policy, ask your insurer in writing before you book, and keep the estimate. We do not promise cashless approval.","payment":"**Payment.** Cash, cards and instalments through a lender may be possible. Terms and fees depend on the hospital and the lender and are not shown here. {tbc}","sources":[{"label":"National Medical Commission: public register of doctors","href":"https://www.nmc.org.in/"}],"footnotes":["Medical review is pending. The reviewer, qualification and review date shown are sample data and will be replaced by the real ones.","The ranges are working figures from one source. They still have to be confirmed in writing for Bestdoctorsin and the partner hospital, and each will carry a date.","Typical timings for an uncomplicated operation, to be confirmed by the reviewer. Your surgeon''s advice overrides this page.","Insurance wording is general and is to be confirmed by the reviewer. Your policy document decides.","Published studies on technique, risk and recovery will be read and cited here after the reviewer opens and checks each one. None is cited yet."]}'::jsonb, '{"titleEm":"(body contouring)","heroPlate":"areas","heroPlateCaption":"Areas where liposuction is commonly planned. A surgeon marks the exact zones on you.","operationHeading":"What the operation involves: tiny cuts, a thin tube and a plan","operationPlate":"cannula","operationCaptions":[{"title":"Before","text":"Fat sits in layers under the skin"},{"title":"During","text":"A thin tube removes it through tiny cuts"}],"recoveryHeading":"Recovery calendar: day 0 to month 12","riskGuideHref":"/liposuction#risks","priceLabel":"One area, usual total bill","priceLinkText":"Other areas and techniques","costMode":"options","costHeading":"What it costs, area by area","costCaption":"Price table by area and technique. Each row is a separate case, so the rows are not added together.","tocLabels":{"surgery":"The operation","choices":"Areas and techniques"}}'::jsonb, '{"hero":{},"operation":{},"recovery":{},"card":{}}'::jsonb, true),
  ('tummy-tuck', 'Tummy tuck', 'Tummy tuck', 'Abdominoplasty', 'For loose skin and weak abdominal muscle after weight change.', '{"procedureType":"https://schema.org/SurgicalProcedure","bodyLocation":"Abdomen","howPerformed":"Extra skin is removed and the abdominal muscle is tightened.","preparation":"Examination, medicine review and an anaesthesia fitness check.","followup":"Compression garment and review visits."}'::jsonb, null, '[]'::jsonb, '2 to 3 weeks', 'For loose skin and weak abdominal muscle after weight change.', 2, '["liposuction","gynecomastia-surgery"]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, null, null, null, false),
  ('rhinoplasty', 'Rhinoplasty', 'Rhinoplasty', 'Nose surgery', 'Surgery to change the shape or the breathing function of the nose.', '{"procedureType":"https://schema.org/SurgicalProcedure","bodyLocation":"Nose","howPerformed":"The bone and cartilage of the nose are reshaped.","preparation":"Examination, medicine review and an anaesthesia fitness check.","followup":"Splint, review visits and a staged return to activity."}'::jsonb, null, '[]'::jsonb, 'To be confirmed', 'Surgery to change the shape or the breathing function of the nose.', 1, '["liposuction"]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, null, null, null, false),
  ('hair-transplant', 'Hair transplant', 'Hair transplant', null, 'Moves hair roots from one part of the scalp to a thinning part.', '{"procedureType":"https://schema.org/SurgicalProcedure","bodyLocation":"Scalp","howPerformed":"Hair roots are taken from a donor area and placed in the thinning area.","preparation":"Scalp examination and medicine review.","followup":"Review visits and wash instructions."}'::jsonb, null, '[]'::jsonb, 'To be confirmed', 'Moves hair roots from one part of the scalp to a thinning part.', 1, '["rhinoplasty"]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, null, null, null, false),
  ('breast-augmentation', 'Breast augmentation', 'Breast augmentation', null, 'Surgery to increase breast size with implants or fat.', '{"procedureType":"https://schema.org/SurgicalProcedure","bodyLocation":"Breast","howPerformed":"An implant is placed through a small cut, or fat is moved from another area.","preparation":"Examination, medicine review and an anaesthesia fitness check.","followup":"Support garment and review visits."}'::jsonb, null, '[]'::jsonb, 'To be confirmed', 'Surgery to increase breast size with implants or fat.', 3, '["tummy-tuck"]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, null, null, null, false)
insert into public.treatment_city_pages (treatment_slug, city_slug, is_placeholder, published, reviewer_id, meta_description, price_min_inr, price_max_inr, price_from_inr, price_valid_as_of, price_collected_on, price_data_points, price_source_type, price_is_sample, price_chip_label, price_basis, includes, facilities, travel, local_context, usefulness, signoffs, lighthouse_ok, before_after, local_copy, images, local_notes) values
  ('gynecomastia-surgery', 'gurgaon', false, true, 'sample-reviewer', 'Gynecomastia surgery in Gurgaon: price lines, recovery calendar, risks, getting there and how we check surgeons.', 62000, 94000, 45000, '2026-11', '2026-11-09', 1, 'founder_published', true, 'To be confirmed', 'Working range, dated 09 Nov 2026, from one source. It covers the three fees listed below. Bills from about Rs 45,000 are possible for small cases.', '{"surgeon":"included","anaesthesia":"included","theatre":"included","stay":"varies","consumables":"unknown","followups":"unknown","medicines":"unknown"}'::jsonb, '{"intro":"The operation is done at a partner facility in Gurgaon, also written Gurugram. We do not name it on this page. Whatever the facility, check the same things.","partners":[{"type":"Partner facility (day care or hospital)","count":null}],"accreditation":null,"checks":[{"check":"Registration","why":"The facility and the surgeon should both be registered","ask":"May I see the facility''s certificate and proof that the surgeon is registered with a medical council?"},{"check":"Accreditation","why":"Shows an outside body has checked its processes","ask":"Which body, and until when is it valid?"},{"check":"Day care or beds","why":"Decides whether you can stay a night if needed","ask":"Is an overnight bed kept for me if the surgeon asks?"},{"check":"Emergency plan","why":"A complication needs a plan, not a phone call","ask":"Where would I be taken if I needed more care?"},{"check":"Billing","why":"Every fee and every extra, before you decide","ask":"Can I have the estimate in writing, with every line?"}]}'::jsonb, '{"intro":"Most people come from Delhi, Noida, Faridabad or Rewari. Plan for one attendant and a ride home that avoids peak traffic.","airport":"Indira Gandhi International Airport, Delhi (to be verified)","station":"HUDA City Centre (Yellow Line) and Sikandarpur (Rapid Metro)","stayDays":"Day care for most; one night if the surgeon asks","metro":"The Delhi Metro Yellow Line runs into Gurugram as far as HUDA City Centre, and Rapid Metro joins it at Sikandarpur. {sample} Nearest station and drive time to the partner facility are added once the facility is confirmed.","roadTimes":[{"from":"South Delhi","time":"40 to 70 min","tip":"Leave before the morning peak"},{"from":"Noida","time":"70 to 110 min","tip":"Plan a night''s stay if the operation is late in the day"},{"from":"Faridabad","time":"60 to 100 min","tip":"Plan the ride home away from peak hour"},{"from":"Rewari","time":"60 to 90 min","tip":"Highway ride, a seat that reclines helps"}],"privacyNote":"Ask the coordinator which entrance is quietest for drop-off. No building name is printed on any message we send. Staying one night is a surgeon''s decision, and your attendant can stay with you.","mapCaption":"Travel from nearby areas, no building shown."}'::jsonb, '[]'::jsonb, '', '{}'::jsonb, false, '[]'::jsonb, '["Most people come from Delhi, Noida, Faridabad or Rewari.","The Delhi Metro Yellow Line runs into Gurugram as far as HUDA City Centre, and Rapid Metro joins it at Sikandarpur."]'::jsonb, null, '[]'::jsonb),
  ('gynecomastia-surgery', 'delhi', false, true, 'sample-reviewer', 'Gynecomastia surgery in Delhi: price lines, recovery, risks, and how a visit from Noida, Ghaziabad or Faridabad is planned.', 62000, 94000, 45000, '2026-11', '2026-11-10', 1, 'founder_published', true, 'To be confirmed', 'Working range from one source, dated 10 Nov 2026. It covers the three fees listed below. The same figure is shown for every city until local quotes are collected. Bills from about Rs 45,000 are possible for small cases.', '{"surgeon":"included","anaesthesia":"included","theatre":"included","stay":"varies","consumables":"unknown","followups":"unknown","medicines":"unknown"}'::jsonb, '{"intro":"No partner facility is confirmed in Delhi yet. Until one is, this page shows how a Delhi plan is made, and the checks to run on any place you are offered. If the surgery turns out to be in Gurgaon, the page will say so plainly.","partners":[{"type":"Partner facility in Delhi (to be confirmed)","count":null}],"accreditation":null,"checks":[{"check":"Registration","why":"The facility and the surgeon should both be registered","ask":"May I see the facility''s certificate and proof that the surgeon is registered with a medical council?"},{"check":"Day care or beds","why":"Decides whether you can stay a night if needed","ask":"Is an overnight bed kept for me if the surgeon asks?"},{"check":"Privacy at the front desk","why":"Many men want a quiet drop-off and discreet paperwork","ask":"Which entrance is used, and what name appears on the billing paper?"},{"check":"Emergency plan","why":"A complication needs a plan, not a phone call","ask":"Where would I be taken if I needed more care?"},{"check":"Billing","why":"Every fee and every extra, before you decide","ask":"Can I have the estimate in writing, with every line?"}]}'::jsonb, '{"intro":"In Delhi the hard part is not distance but traffic. Plan the consultation day and the operation day for off-peak hours, and bring an attendant who can drive you home.","airport":"Indira Gandhi International Airport (to be verified)","station":"New Delhi, Old Delhi and Hazrat Nizamuddin stations (to be verified against the facility)","stayDays":"Day care for most; one night if the surgeon asks","metro":"Most of Delhi is on the metro, but you should not take it home after the operation. A cab with a reclining seat is easier on the chest. {sample} The nearest station to the facility is added once it is confirmed.","roadTimes":[{"from":"Noida","time":"50 to 90 min","tip":"Cross the river before the evening peak"},{"from":"Ghaziabad","time":"60 to 100 min","tip":"Ask for a late-morning slot to miss the rush"},{"from":"Faridabad","time":"50 to 90 min","tip":"Plan the ride home away from peak hour"},{"from":"Gurgaon","time":"50 to 90 min","tip":"Leave before the morning peak"}],"privacyNote":"Ask which entrance is quietest and whether the clothes you wear in can be loose. No building name is printed on any message we send. A night''s stay is a surgeon''s decision, and your attendant can stay with you.","mapCaption":"Travel into Delhi from nearby towns, no building shown."}'::jsonb, '[{"text":"NEEDS REAL DATA: which Delhi facility, if any, will host the operation","source":"","asOf":""},{"text":"NEEDS REAL DATA: metro station and road access to that facility, with a date","source":"","asOf":""}]'::jsonb, '', '{}'::jsonb, false, '[]'::jsonb, '["Delhi pages are written after a partner is confirmed. Until then this page shows how a Delhi plan is made.","Noida, Ghaziabad and Faridabad patients lose most time to traffic, not distance."]'::jsonb, null, '[{"heading":"Where the operation happens","text":"To be confirmed. If it is done in Gurgaon, the [Gurgaon page](/gynecomastia-surgery-in-gurgaon) has the road times and the facility checks. {tbc}"},{"heading":"Choosing a day","text":"Delhi traffic is lightest mid-morning and early afternoon on weekdays. Ask for a morning operation slot so that you are home well before the evening peak."},{"heading":"Air quality and the first week","text":"Winter air in Delhi can be poor. Whether it matters for recovery is a question for the reviewing surgeon. {pending} Until then, plan the first week indoors if you can."},{"heading":"Who comes with you","text":"Bring one adult who can drive. Parking near a hospital can be limited, so ask the coordinator where the attendant can wait."}]'::jsonb),
  ('gynecomastia-surgery', 'lucknow', false, true, 'sample-reviewer', 'Gynecomastia surgery in Lucknow: price lines, recovery, risks, and the trip from Barabanki, Unnao or Sitapur.', 62000, 94000, 45000, '2026-11', '2026-11-10', 1, 'founder_published', true, 'To be confirmed', 'Working range from one source, dated 10 Nov 2026. It covers the three fees listed below. The same figure is shown for every city until local quotes are collected. Bills from about Rs 45,000 are possible for small cases.', '{"surgeon":"included","anaesthesia":"included","theatre":"included","stay":"varies","consumables":"unknown","followups":"unknown","medicines":"unknown"}'::jsonb, '{"intro":"No partner facility is confirmed in Lucknow yet. If the operation ends up being in another city, we will say so at the top of this page and not claim a local site. Whatever the place, run the same checks.","partners":[{"type":"Partner facility in Lucknow (to be confirmed)","count":null}],"accreditation":null,"checks":[{"check":"Registration","why":"The facility and the surgeon should both be registered","ask":"May I see the facility''s certificate and proof that the surgeon is registered with a medical council?"},{"check":"Day care or beds","why":"Decides whether you can stay a night if needed","ask":"Is an overnight bed kept for me if the surgeon asks?"},{"check":"Privacy at the front desk","why":"Many men want a quiet drop-off and discreet paperwork","ask":"Which entrance is used, and what name appears on the billing paper?"},{"check":"Emergency plan","why":"A complication needs a plan, not a phone call","ask":"Where would I be taken if I needed more care?"},{"check":"Billing","why":"Every fee and every extra, before you decide","ask":"Can I have the estimate in writing, with every line?"}]}'::jsonb, '{"intro":"Many people who ask about this surgery in Lucknow live in a town outside it and come in for the day. The plan is built around one early train or road trip in, and one ride home with a seat that reclines.","airport":"Chaudhary Charan Singh International Airport, Lucknow (to be verified)","station":"Charbagh station and the Lucknow Metro (to be verified against the facility)","stayDays":"Day care for most; one night if the surgeon asks or the road home is long","metro":"The Lucknow Metro runs along the north-south corridor and is useful for the consultation visit. After the operation a cab is easier. {sample} Station names and distances to the facility are added once it is confirmed.","roadTimes":[{"from":"Barabanki","time":"40 to 70 min","tip":"Short enough for a same-day return if the surgeon agrees"},{"from":"Unnao","time":"60 to 100 min","tip":"Consider a night in Lucknow if the operation is late in the day"},{"from":"Sitapur","time":"80 to 120 min","tip":"Ask whether the first review can be on a video call"},{"from":"Hardoi","time":"100 to 150 min","tip":"Plan a night''s stay and book the return by road, not train"}],"privacyNote":"If you come from a smaller town, tell the coordinator early who may know you at the hospital. A cousin or a neighbour at the front desk is a real worry for many men, and a quiet entrance or a different slot can help.","mapCaption":"Travel into Lucknow from nearby districts, no building shown."}'::jsonb, '[{"text":"NEEDS REAL DATA: which Lucknow facility, if any, will host the operation","source":"","asOf":""},{"text":"NEEDS REAL DATA: road times from Barabanki, Unnao, Sitapur and Hardoi, checked on a map with a date","source":"","asOf":""},{"text":"NEEDS REAL DATA: guest-house or hotel options near the facility","source":"","asOf":""}]'::jsonb, '', '{}'::jsonb, false, '[]'::jsonb, '["Many people ask about this surgery in Lucknow from a town outside it, and come in for the day.","A first review on a video call can save a second long trip to the city."]'::jsonb, null, '[{"heading":"Coming in from a smaller town","text":"Decide before you book whether you will go home the same day or stay a night. Roads out of Lucknow in the evening are slow, and an early operation slot makes a same-day return realistic for nearby towns."},{"heading":"Language","text":"Hindi and Hinglish are fine for the first call and for the consultation. Ask for the written estimate in the language you read most easily. {tbc}"},{"heading":"Summer heat and the vest","text":"May and June heat makes the compression vest hard to wear. Ask for a breathable garment and a spare, and plan the first week in a cool room."},{"heading":"If you live in Kanpur","text":"Lucknow is the nearest other city we cover for Kanpur patients. Read the [Kanpur page](/gynecomastia-surgery-in-kanpur) to compare the trip."}]'::jsonb),
  ('gynecomastia-surgery', 'kanpur', false, true, 'sample-reviewer', 'Gynecomastia surgery in Kanpur: price lines, recovery, risks, and whether the operation is in Kanpur or a short trip away.', 62000, 94000, 45000, '2026-11', '2026-11-10', 1, 'founder_published', true, 'To be confirmed', 'Working range from one source, dated 10 Nov 2026. It covers the three fees listed below. The same figure is shown for every city until local quotes are collected. Bills from about Rs 45,000 are possible for small cases.', '{"surgeon":"included","anaesthesia":"included","theatre":"included","stay":"varies","consumables":"unknown","followups":"unknown","medicines":"unknown"}'::jsonb, '{"intro":"No partner facility is confirmed in Kanpur yet. It is possible that people from Kanpur will be asked to travel for the operation, and if so this page will say where and how far, before anything else.","partners":[{"type":"Partner facility for Kanpur patients (to be confirmed)","count":null}],"accreditation":null,"checks":[{"check":"Registration","why":"The facility and the surgeon should both be registered","ask":"May I see the facility''s certificate and proof that the surgeon is registered with a medical council?"},{"check":"Day care or beds","why":"Decides whether you can stay a night if needed","ask":"Is an overnight bed kept for me if the surgeon asks?"},{"check":"Privacy at the front desk","why":"Many men want a quiet drop-off and discreet paperwork","ask":"Which entrance is used, and what name appears on the billing paper?"},{"check":"Emergency plan","why":"A complication needs a plan, not a phone call","ask":"Where would I be taken if I needed more care?"},{"check":"Billing","why":"Every fee and every extra, before you decide","ask":"Can I have the estimate in writing, with every line?"}]}'::jsonb, '{"intro":"For Kanpur the first question is where the operation is. If it is in Kanpur, plan a local day-care visit. If it is in Lucknow, plan a trip of roughly one and a half to two hours each way, and think about a night away.","airport":"Kanpur civil airport and Lucknow airport (service and schedules to be verified)","station":"Kanpur Central, and Charbagh in Lucknow (to be verified)","stayDays":"Day care for most; one night if the surgeon asks or travel is long","metro":"Kanpur has a metro that is being extended; whether it serves the facility is to be checked. {sample} For the trip to Lucknow, rail and road both run between the two cities, and the road is the easier ride home.","roadTimes":[{"from":"Unnao","time":"30 to 60 min","tip":"Close enough for a same-day consultation"},{"from":"Kanpur Dehat","time":"40 to 80 min","tip":"Ask for an early slot for the operation"},{"from":"Fatehpur","time":"70 to 110 min","tip":"Plan a night in Kanpur after the operation"},{"from":"Lucknow","time":"100 to 150 min","tip":"The other city we cover; compare before you book"}],"privacyNote":"Kanpur is a city where people often know each other. Ask which entrance is used and whether the first review can be a video call, so that you travel less in the first two weeks.","mapCaption":"Travel in and out of Kanpur, no building shown."}'::jsonb, '[{"text":"NEEDS REAL DATA: whether a Kanpur facility exists for this operation, or patients go to Lucknow","source":"","asOf":""},{"text":"NEEDS REAL DATA: timings of trains and buses between Kanpur and Lucknow, with a date","source":"","asOf":""}]'::jsonb, '', '{}'::jsonb, false, '[]'::jsonb, '["For Kanpur patients the first question is where the operation is, in Kanpur or a short trip away.","A first review by video can save the second trip after the operation."]'::jsonb, null, '[{"heading":"Do I have to leave Kanpur?","text":"To be confirmed. Until a Kanpur partner exists, the likeliest plan is a consultation by call, then a trip to the facility for the operation. The page will say so clearly if that is the case. {tbc}"},{"heading":"Follow-up after you go home","text":"Ask which review visits must be in person and which can be on a video call. The first check at about a week matters most, and you may be asked to attend it in person."},{"heading":"Train and road","text":"If you travel to Lucknow, the road is the easier way home with a compression vest on. Ask the coordinator for a cab that reclines. Train timings are to be added after they are checked. {pending}"},{"heading":"Family and stay","text":"If you stay a night away, one family member can usually stay with you. Ask about guest-house options near the facility."}]'::jsonb),
  ('liposuction', 'gurgaon', false, true, 'sample-reviewer', 'Liposuction in Gurgaon: price by area, recovery, risks, and the trip from Delhi, Noida, Faridabad or Rewari.', 60000, 80000, null, '2026-11', '2026-11-10', 1, 'founder_published', true, 'To be confirmed', 'Working range for one area, such as the abdomen or the arms, from one source dated 10 Nov 2026. Two areas, ultrasound-assisted work, full-body plans and the chin cost differently, so see the table. The same figures are shown for every city until local quotes are collected.', '{"surgeon":"unknown","anaesthesia":"unknown","theatre":"unknown","stay":"varies","consumables":"unknown","followups":"unknown","medicines":"unknown"}'::jsonb, '{"intro":"A liposuction plan in Gurgaon, also written Gurugram, is done at a partner facility that we do not name on this page. Larger plans with several areas need a hospital with an anaesthesia team, and small ones may suit a day-care centre. Ask which one your plan needs.","partners":[{"type":"Partner facility (day care or hospital)","count":null}],"accreditation":null,"checks":[{"check":"Registration and accreditation","why":"An outside body should have checked the facility, and the surgeon should be on a medical council''s register","ask":"Which body accredits the facility, until when, and where can I check the surgeon''s registration?"},{"check":"Anaesthesia team","why":"Larger or several-area plans need a separate anaesthetist, and a plan for monitoring","ask":"Who gives the anaesthetic, and how is my breathing and blood pressure watched after the operation?"},{"check":"Limit on fat removed in one session","why":"Removing a very large volume at once raises the risk","ask":"What limit do you keep for one session, and would you split a large plan?"},{"check":"Garments and follow-up","why":"The first garment and the first visit decide how the shape settles","ask":"Which garments are included, and how many visits are in the quote?"},{"check":"Clot prevention and emergencies","why":"Clots are rare but serious after larger operations","ask":"What do you do to lower the risk of clots, and where would I go in an emergency?"}]}'::jsonb, '{"intro":"People come to Gurgaon for liposuction from across the Delhi region. Several areas treated at once means a longer day and a garment under your clothes on the ride home, so plan the trip with that in mind.","airport":"Indira Gandhi International Airport, Delhi (to be verified)","station":"HUDA City Centre (Yellow Line) and Sikandarpur (Rapid Metro)","stayDays":"Day care for small plans; a night for larger ones if the surgeon asks","metro":"The Yellow Line reaches HUDA City Centre and Rapid Metro joins it at Sikandarpur, which suits the consultation visit. After a larger plan a cab is more comfortable. {sample}","roadTimes":[{"from":"South Delhi","time":"40 to 70 min","tip":"A garment feels tight in a long jam, so leave off-peak"},{"from":"Noida","time":"70 to 110 min","tip":"For several areas, book a night nearby"},{"from":"Faridabad","time":"60 to 100 min","tip":"Bring a loose, dark set of clothes to wear home"},{"from":"Rewari","time":"60 to 90 min","tip":"A reclining seat and a pillow for the ride"}],"privacyNote":"The coordinator can tell you which entrance is quiet. No building name is printed on any message we send. If you are staying a night, one adult can stay with you.","mapCaption":"Travel into Gurgaon from nearby areas, no building shown."}'::jsonb, '[{"text":"NEEDS REAL DATA: the partner facility''s anaesthesia set-up for multi-area plans","source":"","asOf":""},{"text":"NEEDS REAL DATA: drive time from the facility to the nearest metro station","source":"","asOf":""}]'::jsonb, '', '{}'::jsonb, false, '[]'::jsonb, '["Several areas treated at once means a longer day and a garment under your clothes on the ride home.","Larger plans need a hospital with an anaesthesia team; small ones may suit a day-care centre."]'::jsonb, null, '[{"heading":"Small plan or large plan","text":"A single small area may be done as day care. Two or more areas, or an ultrasound-assisted plan, often need a longer anaesthetic and more recovery time. Ask the surgeon which of the two your plan is before you choose a facility."},{"heading":"Corporate schedules","text":"Many people from Gurgaon offices plan the operation on a Thursday or Friday so that a weekend sits inside the first days of rest. Whether it is wise for you is a question for the surgeon. {pending}"},{"heading":"Heat and the garment","text":"From April to September the garment is hard to wear in a Gurgaon summer. Ask for a breathable fabric and a spare, and plan the first week in a cool room."},{"heading":"If you live in Delhi","text":"Delhi is close, but the roads are slow. See the [Delhi page](/liposuction-in-delhi) to compare the trip."}]'::jsonb),
  ('liposuction', 'delhi', false, true, 'sample-reviewer', 'Liposuction in Delhi: price by area, recovery, risks, and how a visit from Noida, Ghaziabad or Faridabad is planned.', 60000, 80000, null, '2026-11', '2026-11-10', 1, 'founder_published', true, 'To be confirmed', 'Working range for one area, such as the abdomen or the arms, from one source dated 10 Nov 2026. Two areas, ultrasound-assisted work, full-body plans and the chin cost differently, so see the table. The same figures are shown for every city until local quotes are collected.', '{"surgeon":"unknown","anaesthesia":"unknown","theatre":"unknown","stay":"varies","consumables":"unknown","followups":"unknown","medicines":"unknown"}'::jsonb, '{"intro":"No partner facility is confirmed in Delhi yet. Until one is, this page shows how a Delhi liposuction plan is made, and the checks to run on any facility. If the work is done in Gurgaon, the page will say so first.","partners":[{"type":"Partner facility in Delhi (to be confirmed)","count":null}],"accreditation":null,"checks":[{"check":"Registration and accreditation","why":"An outside body should have checked the facility, and the surgeon should be on a medical council''s register","ask":"Which body accredits the facility, until when, and where can I check the surgeon''s registration?"},{"check":"Anaesthesia team","why":"Larger or several-area plans need a separate anaesthetist, and a plan for monitoring","ask":"Who gives the anaesthetic, and how is my breathing and blood pressure watched after the operation?"},{"check":"Limit on fat removed in one session","why":"Removing a very large volume at once raises the risk","ask":"What limit do you keep for one session, and would you split a large plan?"},{"check":"Garments and follow-up","why":"The first garment and the first visit decide how the shape settles","ask":"Which garments are included, and how many visits are in the quote?"},{"check":"Clot prevention and emergencies","why":"Clots are rare but serious after larger operations","ask":"What do you do to lower the risk of clots, and where would I go in an emergency?"}]}'::jsonb, '{"intro":"A body-contouring plan in Delhi usually means one consultation, one operation day and a first review within the week. Three trips across the city add up, so ask which of them can be done by video.","airport":"Indira Gandhi International Airport (to be verified)","station":"New Delhi, Old Delhi and Hazrat Nizamuddin stations (to be verified against the facility)","stayDays":"Day care for small plans; one night for larger ones if the surgeon asks","metro":"The metro is useful for the consultation and the first review, but a cab with a reclining seat is better after the operation. {sample} The nearest station to the facility is added once it is confirmed.","roadTimes":[{"from":"Noida","time":"50 to 90 min","tip":"Plan the first review for a mid-morning slot"},{"from":"Ghaziabad","time":"60 to 100 min","tip":"Ask if the first review can be a video call"},{"from":"Faridabad","time":"50 to 90 min","tip":"Wear loose clothes that fit over the garment"},{"from":"Gurgaon","time":"50 to 90 min","tip":"Consider a night nearby after a larger plan"}],"privacyNote":"Ask which entrance is used, whether billing papers carry only your name, and whether you can leave by a side door. A garment is hidden by loose clothes, so pack a size up.","mapCaption":"Travel into Delhi from nearby towns, no building shown."}'::jsonb, '[{"text":"NEEDS REAL DATA: which Delhi facility, if any, will host liposuction plans","source":"","asOf":""},{"text":"NEEDS REAL DATA: whether the Delhi facility keeps a bed for an overnight stay after larger plans","source":"","asOf":""}]'::jsonb, '', '{}'::jsonb, false, '[]'::jsonb, '["A body-contouring plan in Delhi usually means one consultation, one operation day and a first review within the week.","Three trips across the city add up, so ask which of them can be done by video."]'::jsonb, null, '[{"heading":"Where the operation happe