-- Release 2 for staging. Generated by `npm run seed:sql`. Safe to run repeatedly.
-- Run supabase/migrations/0001_init.sql first (already done on the live database).
-- This file: (1) applies the 0002 changes, (2) upserts all content, (3) publishes the written pages and guides.
-- Published pages still stay noindex on the site: sample prices, a placeholder reviewer and missing sign-offs fail the publish gate.

-- Release 2. Idempotent: safe to run more than once (also run by supabase/seed-add.sql).
-- Adds image slots, display wording and local notes, and makes cost lines unique.

alter table public.treatments           add column if not exists display     jsonb;
alter table public.treatments           add column if not exists images      jsonb;
alter table public.treatment_city_pages add column if not exists images      jsonb;
alter table public.treatment_city_pages add column if not exists local_notes jsonb not null default '[]';
alter table public.blog_posts           add column if not exists cover       jsonb;
alter table public.blog_posts           add column if not exists next_cities jsonb;

-- Duplicate cost lines appear when a seed file is run twice. Keep the lowest id of each line, then forbid repeats.
delete from public.costs a
 using public.costs b
 where a.treatment_slug = b.treatment_slug
   and coalesce(a.city_slug, '') = coalesce(b.city_slug, '')
   and a.position = b.position
   and a.id > b.id;

create unique index if not exists costs_unique_line
  on public.costs (treatment_slug, coalesce(city_slug, ''), position);

on conflict (id) do update set name = excluded.name, credential = excluded.credential, reviewed_on = excluded.reviewed_on, is_sample = excluded.is_sample, photo_consent = excluded.photo_consent, published = excluded.published;

on conflict (slug) do update set name = excluded.name, alt_name = excluded.alt_name, state = excluded.state, areas = excluded.areas, summary = excluded.summary, nearby = excluded.nearby, published = excluded.published;

on conflict (slug) do update set name = excluded.name, menu_name = excluded.menu_name, alternate_name = excluded.alternate_name, summary = excluded.summary, procedure = excluded.procedure, national_range = excluded.national_range, cost_factors = excluded.cost_factors, desk_work = excluded.desk_work, card_blurb = excluded.card_blurb, icon = excluded.icon, related = excluded.related, read_slugs = excluded.read_slugs, video_slugs = excluded.video_slugs, reviewer_id = excluded.reviewer_id, content = excluded.content, display = excluded.display, images = excluded.images, published = excluded.published;

on conflict (treatment_slug, city_slug) do update set is_placeholder = excluded.is_placeholder, published = excluded.published, reviewer_id = excluded.reviewer_id, meta_description = excluded.meta_description, price_min_inr = excluded.price_min_inr, price_max_inr = excluded.price_max_inr, price_from_inr = excluded.price_from_inr, price_valid_as_of = excluded.price_valid_as_of, price_collected_on = excluded.price_collected_on, price_data_points = excluded.price_data_points, price_source_type = excluded.price_source_type, price_is_sample = excluded.price_is_sample, price_chip_label = excluded.price_chip_label, price_basis = excluded.price_basis, includes = excluded.includes, facilities = excluded.facilities, travel = excluded.travel, local_context = excluded.local_context, usefulness = excluded.usefulness, signoffs = excluded.signoffs, lighthouse_ok = excluded.lighthouse_ok, before_after = excluded.before_after, local_copy = excluded.local_copy, images = excluded.images, local_notes = excluded.local_notes;

on conflict (treatment_slug, (coalesce(city_slug, '')), position) do update set component = excluded.component, min_inr = excluded.min_inr, max_inr = excluded.max_inr, note = excluded.note;

on conflict (id) do update set treatment_slug = excluded.treatment_slug, city_slug = excluded.city_slug, position = excluded.position, question = excluded.question, answer = excluded.answer, published = excluded.published;

on conflict (slug) do update set title = excluded.title, excerpt = excluded.excerpt, minutes = excluded.minutes, thumb = excluded.thumb, treatment_slug = excluded.treatment_slug, body = excluded.body, reviewer_id = excluded.reviewer_id, published = excluded.published, date_published = excluded.date_published, date_modified = excluded.date_modified, cover = excluded.cover, next_cities = excluded.next_cities;

on conflict (slug) do update set title = excluded.title, duration = excluded.duration, iso_duration = excluded.iso_duration, description = excluded.description, transcript = excluded.transcript, poster = excluded.poster, poster_alt = excluded.poster_alt, youtube_id = excluded.youtube_id, upload_date = excluded.upload_date, is_sample = excluded.is_sample, published = excluded.published;

-- Check: expect treatments 2, pages 8, guides 24 or more, cost lines 8 for gynecomastia and 5 for liposuction.
select 'published treatments' as what, count(*) from public.treatments where published
union all select 'published pages', count(*) from public.treatment_city_pages where published
union all select 'published guides', count(*) from public.blog_posts where published
union all select 'cost lines', count(*) from public.costs;
